it('`die()` pays loot and XP even in PLAYBACK, with no death sound and no roll — all four (`EnemyHorse.as:257-266` vs `NPC.as:903-908`)', () => {
  for (const [name, make, clip] of [
    ['bear', bear, OG_ANIM.BEAR_DEATH],
    ['deer', deer, OG_ANIM.DEER_DEATH],
    ['horse', horse, OG_ANIM.HORSE_DEATH],
    ['stag', stag, OG_ANIM.HORSE_DEATH],
  ] as const) {
    const a = make({ world: { playback: true } }).npc;
    a.setPosition(400, 100);
    a.die();
    expect(ofType(a, 'xp'), name).toHaveLength(1); // the base pays nothing in playback
    expect(ofType(a, 'sound'), name).toHaveLength(0);
    expect(a.y, name).toBe(GROUND);
    expect(a.actionState, name).toBe(OG_STATE.DYING);
    expect(ofType(a, 'death'), name).toEqual([{ type: 'death', anim: clip, behead: false, downed: false, dice: -1 }]);
    expect(a.dead, name).toBe(true);
  }
});

